const SERVER='https://180-hitters-online.180-hitters-online.workers.dev';
const KEY='180hitters.club.v1';
let account={};
try{account=JSON.parse(localStorage.getItem(KEY)||'{}');}catch{}
const save=()=>localStorage.setItem(KEY,JSON.stringify(account));
const api=async(path,body)=>{const response=await fetch(SERVER+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||`Verzoek mislukt (${response.status}).`);return data;};
const style=document.createElement('style');style.textContent='.club-dialog{width:min(620px,calc(100vw - 24px));max-height:90vh}.club-dialog section,.club-dialog details{margin:12px 0;padding:14px;border:1px solid var(--line);border-radius:14px}.club-dialog details summary{cursor:pointer;color:var(--accent);font-weight:800}.club-admin-head,.club-member,.club-member>div{display:flex;align-items:center;justify-content:space-between;gap:8px}.club-member{padding:10px 0;border-bottom:1px solid var(--line)}.club-member>span{overflow-wrap:anywhere}.club-member button{padding:7px 9px;font-size:12px}#club-members{max-height:300px;overflow:auto}#club-status{min-height:22px;color:#ffd09c}@media(max-width:600px){.club-member{align-items:stretch;flex-direction:column}.club-member>div{display:grid;grid-template-columns:1fr 1fr}.club-member button{width:100%}}';document.head.append(style);
const open=document.createElement('button');open.id='club-open';open.type='button';open.textContent='Clubregistratie';document.getElementById('top-actions').append(open);
const dialog=document.createElement('dialog');dialog.id='club-dialog';dialog.className='club-dialog';dialog.innerHTML=`<h2>Clubregistratie</h2><p id="club-summary">Online darten is alleen beschikbaar voor goedgekeurde clubspelers.</p><section id="club-register"><label>Jouw naam<input id="club-name" maxlength="24" autocomplete="name"></label><label>Clubcode<input id="club-code" maxlength="40" autocomplete="off"></label><button id="club-request" class="primary wide">Toegang aanvragen</button></section><section id="club-wait" hidden><p id="club-wait-text"></p><button id="club-refresh" class="primary wide">Status controleren</button></section><details id="club-admin-activate"><summary>Beheerder activeren</summary><label>Naam<input id="club-admin-name" maxlength="24" value="Axelman8"></label><label>Beheerderscode<input id="club-admin-code" type="password" autocomplete="off"></label><button id="club-activate" class="wide">Activeren</button></details><section id="club-admin" hidden><div class="club-admin-head"><strong>Aanvragen beheren</strong><button id="club-admin-refresh">Vernieuwen</button></div><div id="club-members"></div></section><p id="club-status" role="status"></p><button id="club-close" class="wide">Sluiten</button>`;document.body.append(dialog);
const $=id=>document.getElementById(id);
export const clubAccessToken=()=>account.accessToken||'';
export const clubPlayerName=()=>account.member?.name||'';
export function openClubDialog(){render();dialog.showModal();void refresh();}
export async function requireClubAccess(){if(account.accessToken){try{await refresh();if(account.member?.status==='approved')return true;}catch{}}openClubDialog();$('club-status').textContent='Vraag eerst toegang aan of wacht op goedkeuring.';return false;}
function statusLabel(value){return value==='approved'?'Goedgekeurd':value==='pending'?'Wacht op goedkeuring':value==='blocked'?'Geblokkeerd':'Afgewezen';}
function render(){const member=account.member,approved=member?.status==='approved';$('club-register').hidden=!!member;$('club-wait').hidden=!member||approved;$('club-admin-activate').hidden=!!account.adminToken;$('club-admin').hidden=!account.adminToken;if(member){$('club-summary').textContent=`${member.name}: ${statusLabel(member.status)}${member.isAdmin?' (beheerder)':''}.`;$('club-wait-text').textContent=member.status==='pending'?'Jouw aanvraag staat klaar. Axel krijgt deze in het beheer te zien.':`De toegang is ${statusLabel(member.status).toLowerCase()}.`;}else $('club-summary').textContent='Vul de clubcode in. Axel keurt jouw aanvraag daarna goed.';open.textContent=approved?'Clubspeler'+(account.pending?` (${account.pending})`:''):member?'Clubregistratie wacht':'Clubregistratie';}
async function refresh(){try{if(account.requestToken||account.accessToken){const data=await api('/club/status',{requestToken:account.requestToken,accessToken:account.accessToken});account.member=data.member;if(data.accessToken)account.accessToken=data.accessToken;save();}if(account.adminToken)await loadMembers();render();}catch(error){$('club-status').textContent=error.message;}}
async function loadMembers(){const data=await api('/club/admin/list',{adminToken:account.adminToken});account.pending=data.pending||0;save();const list=$('club-members');list.replaceChildren();for(const member of data.members){const row=document.createElement('div');row.className='club-member';const label=document.createElement('span');label.textContent=`${member.name} - ${statusLabel(member.status)}${member.isAdmin?' - beheerder':''}`;const actions=document.createElement('div');if(!member.isAdmin){for(const [action,text] of [['approve','Goedkeuren'],['reject','Afwijzen'],['block','Blokkeren'],['delete','Verwijderen']]){if(action==='approve'&&member.status==='approved')continue;const button=document.createElement('button');button.type='button';button.textContent=text;button.onclick=async()=>{button.disabled=true;try{await api('/club/admin/action',{adminToken:account.adminToken,id:member.id,action});await loadMembers();render();}catch(error){$('club-status').textContent=error.message;}finally{button.disabled=false;}};actions.append(button);}}row.append(label,actions);list.append(row);}render();}
open.onclick=openClubDialog;$('club-close').onclick=()=>dialog.close();$('club-refresh').onclick=refresh;$('club-admin-refresh').onclick=loadMembers;
$('club-request').onclick=async()=>{const button=$('club-request');button.disabled=true;try{const data=await api('/club/register',{name:$('club-name').value.trim(),clubCode:$('club-code').value.trim()});account={...account,member:data.member,requestToken:data.requestToken};save();render();$('club-status').textContent='Aanvraag verstuurd. Axel kan deze nu goedkeuren.';}catch(error){$('club-status').textContent=error.message;}finally{button.disabled=false;}};
$('club-activate').onclick=async()=>{const button=$('club-activate');button.disabled=true;try{const data=await api('/club/admin/activate',{name:$('club-admin-name').value.trim(),adminCode:$('club-admin-code').value});account={...account,member:data.member,accessToken:data.accessToken,adminToken:data.adminToken};save();render();await loadMembers();$('club-status').textContent='Beheerder geactiveerd.';}catch(error){$('club-status').textContent=error.message;}finally{button.disabled=false;}};
render();setInterval(()=>{if(account.requestToken||account.adminToken)void refresh();},30000);
